    pending = [(word, 1)]
    while pending:
        w, sign = pending.pop()
        k = 0
        while k + 1 < len(w):
            c, m = w[k]
            d, n = w[k + 1]
            if c == d and m == n:
                break
            if c < d or (c == d and m > n):
                break
            k += 1
        if k + 1 >= len(w):
            result[w] = result.get(w, 0) + sign
        elif c != d or m != n:
            swapped = w[:k] + (w[k + 1], w[k]) + w[k + 2:]
            pending.append((swapped, -sign))
            if c == 0 and d == 1 and m == n:
                pending.append((w[:k] + w[k + 2:], sign))
    return {w: a for w, a in result.items() if a}


def lift(left, right, diagonal):
    weights = {}
    if diagonal:
        for p, entry in enumerate(left):
            i, a = entry
            weights[(i, i)] = a * a
            for q in range(p + 1, len(left)):
                j, b = left[q]
                weights[(i, j)] = 2 * a * b
